import{_ as a,a0 as s,w as o,s as u,I as t,x as n,a1 as i,A as l,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux有問必答：如何在Linux上安裝內核頭文件 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在Linux上安裝內核頭文件 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在Linux上安裝內核頭文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在Linux上安裝內核頭文件 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141224 Linux FAQs with Answers--How to install kernel headers on Linux","title":"Linux有問必答：如何在Linux上安裝內核頭文件","tag":"201501","desc":""},"relativePath":"201501/20141224 Linux FAQs with Answers--How to install kernel headers on Linux.md","filePath":"[post].md"}'),d={name:"201501/20141224 Linux FAQs with Answers--How to install kernel headers on Linux.md"};function x(m,e,L,k,f,g){const r=s("Link");return o(),u("div",null,[e[16]||(e[16]=t("h1",{id:"linux有問必答-如何在linux上安裝內核頭文件",tabindex:"-1"},[n("Linux有問必答：如何在Linux上安裝內核頭文件 "),t("a",{class:"header-anchor",href:"#linux有問必答-如何在linux上安裝內核頭文件","aria-label":"Permalink to “Linux有問必答：如何在Linux上安裝內核頭文件”"},"​")],-1)),e[17]||(e[17]=t("blockquote",null,[t("p",null,[t("strong",null,"提問"),n(":我在安裝一個設備驅動前先要安裝內核頭文件。怎樣安裝合適的內核頭文件？")])],-1)),e[18]||(e[18]=t("p",null,"當你在編譯一個設備驅動模組時，你需要在系統中安裝內核頭文件。內核頭文件同樣在你編譯與內核直接鏈接的用户空間程序時需要。當你在這些情況下安裝內核頭文件時，你必須確保內核頭文件精確地與你當前內核版本匹配（比如：3.13.0-24-generic）。",-1)),t("p",null,[e[2]||(e[2]=n("如果你的內核是發行版自帶的內核版本，或者使用默認的包管理器的基礎倉庫升級的（比如：apt-ger、aptitude或者yum），你也可以使用包管理器來安裝內核頭文件。另一方面，如果下載的是",-1)),i(r,{href:"https://www.kernel.org/pub/linux/kernel/"},{default:l(()=>[...e[0]||(e[0]=[n("kernel源碼",-1)])]),_:1}),e[3]||(e[3]=n("並且手動編譯的，你可以使用",-1)),i(r,{href:"https://www.kernel.org/doc/Documentation/kbuild/headers_install.txt"},{default:l(()=>[...e[1]||(e[1]=[n("make命令",-1)])]),_:1}),e[4]||(e[4]=n("來安裝匹配的內核頭文件。",-1))]),e[19]||(e[19]=p(`<p>現在我們假設你的內核是發行版自帶的，讓我們看下該如何安裝匹配的頭文件。</p><h3 id="在-debian、ubuntu-或者-linux-mint-上安裝內核頭文件" tabindex="-1">在 Debian、Ubuntu 或者 Linux Mint 上安裝內核頭文件 <a class="header-anchor" href="#在-debian、ubuntu-或者-linux-mint-上安裝內核頭文件" aria-label="Permalink to “在 Debian、Ubuntu 或者 Linux Mint 上安裝內核頭文件”">​</a></h3><p>假設你沒有手動編譯內核，你可以使用apt-get命令來安裝匹配的內核頭文件。</p><p>首先，使用dpkg-query命令檢查是否有可用的內核頭文件。</p><pre><code>$ dpkg-query -s linux-headers-$(uname -r) 
</code></pre><hr><pre><code>dpkg-query: package &#39;linux-headers-3.11.0-26-generic&#39; is not installed and no information is available
</code></pre><p>接着使用下面的命令安裝匹配的內核頭文件。</p><pre><code>$ sudo apt-get install linux-headers-$(uname -r) 
</code></pre><p><img src="https://farm9.staticflickr.com/8681/16000652415_a7c399992e_z.jpg" alt=""></p><p>驗證頭文件是否成功安裝。</p><pre><code>$ dpkg-query -s linux-headers-$(uname -r) 
</code></pre><hr><pre><code>Package: linux-headers-3.11.0-26-generic
Status: install ok installed
</code></pre><p>Debian、Ubuntu、Linux Mint默認頭文件在<strong>/usr/src</strong>下。</p><h3 id="在-fedora、centos-或者-rhel-上安裝內核頭文件" tabindex="-1">在 Fedora、CentOS 或者 RHEL 上安裝內核頭文件 <a class="header-anchor" href="#在-fedora、centos-或者-rhel-上安裝內核頭文件" aria-label="Permalink to “在 Fedora、CentOS 或者 RHEL 上安裝內核頭文件”">​</a></h3><p>假設你沒有手動編譯內核，你可以使用yum命令來安裝匹配的內核頭文件。</p><p>首先，用下面的命令檢查系統是否已經安裝了頭文件。如果下面的命令沒有任何輸出，這就意味着還沒有頭文件。</p><pre><code>$ rpm -qa | grep kernel-headers-$(uname -r)
</code></pre><p>接着用yum命令安裝頭文件。這個命令會自動找出合適的頭文件並安裝。</p><pre><code>$ sudo yum install kernel-headers 
</code></pre><p><img src="https://farm9.staticflickr.com/8594/15378403114_c51ff6f4ae_z.jpg" alt=""></p><p>驗證包安裝的狀態。</p><pre><code>$ rpm -qa | grep kernel-headers-$(uname -r) 
</code></pre><hr><pre><code>kernel-headers-3.10.0-123.9.3.el7.x86_64
</code></pre><p>Fedora、CentOS 或者 RHEL上默認內核頭文件的位置是<strong>/usr/include/linux</strong>。</p><hr>`,28)),t("p",null,[e[6]||(e[6]=n("via: ",-1)),i(r,{href:"http://ask.xmodulo.com/install-kernel-headers-linux.html"},{default:l(()=>[...e[5]||(e[5]=[n("http://ask.xmodulo.com/install-kernel-headers-linux.html",-1)])]),_:1})]),t("p",null,[e[9]||(e[9]=n("譯者：",-1)),i(r,{href:"https://github.com/geekpi"},{default:l(()=>[...e[7]||(e[7]=[n("geekpi",-1)])]),_:1}),e[10]||(e[10]=n(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:l(()=>[...e[8]||(e[8]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=n("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[11]||(e[11]=[n("LCTT",-1)])]),_:1}),e[14]||(e[14]=n(" 原創翻譯，",-1)),i(r,{href:"http://linux.cn/"},{default:l(()=>[...e[12]||(e[12]=[n("Linux中國",-1)])]),_:1}),e[15]||(e[15]=n(" 榮譽推出",-1))])])}const w=a(d,[["render",x]]);export{T as __pageData,w as default};
